/* script.js から build.py で生成。直接編集しない */
'use strict';
const pad=(n)=>String(n).padStart(2,'0');
const dateKey=(y,m,d)=>`${y}-${pad(m)}-${pad(d)}`;
function nthMonday(year,month,n){
const firstDow=new Date(year,month-1,1).getDay();
const firstMonday=1+((8-firstDow)%7);
return firstMonday+(n-1)*7;
}
function vernalEquinoxDay(year){
return Math.floor(20.8431+0.242194*(year-1980)-Math.floor((year-1980)/4));
}
function autumnalEquinoxDay(year){
return Math.floor(23.2488+0.242194*(year-1980)-Math.floor((year-1980)/4));
}
function getHolidays(year){
const base=[
[1,1,'元日'],
[1,nthMonday(year,1,2),'成人の日'],
[2,11,'建国記念の日'],
[2,23,'天皇誕生日'],
[3,vernalEquinoxDay(year),'春分の日'],
[4,29,'昭和の日'],
[5,3,'憲法記念日'],
[5,4,'みどりの日'],
[5,5,'こどもの日'],
[7,nthMonday(year,7,3),'海の日'],
[8,11,'山の日'],
[9,nthMonday(year,9,3),'敬老の日'],
[9,autumnalEquinoxDay(year),'秋分の日'],
[10,nthMonday(year,10,2),'スポーツの日'],
[11,3,'文化の日'],
[11,23,'勤労感謝の日'],
];
const holidays=new Map();
for(const[m,d,name]of base)holidays.set(dateKey(year,m,d),name);
for(const[m,d]of base){
const next=new Date(year,m-1,d+2);
const nextKey=dateKey(next.getFullYear(),next.getMonth()+1,next.getDate());
const between=new Date(year,m-1,d+1);
const betweenKey=dateKey(between.getFullYear(),between.getMonth()+1,between.getDate());
if(holidays.has(nextKey)&&!holidays.has(betweenKey)&&between.getDay()!==0){
holidays.set(betweenKey,'国民の休日');
}
}
for(const[key]of[...holidays]){
const[y,m,d]=key.split('-').map(Number);
if(new Date(y,m-1,d).getDay()!==0)continue;
let offset=1;
let sub;
do{
sub=new Date(y,m-1,d+offset);
offset+=1;
}while(holidays.has(dateKey(sub.getFullYear(),sub.getMonth()+1,sub.getDate())));
holidays.set(dateKey(sub.getFullYear(),sub.getMonth()+1,sub.getDate()),'振替休日');
}
return holidays;
}
const holidayCache=new Map();
function holidayName(date){
const y=date.getFullYear();
if(!holidayCache.has(y))holidayCache.set(y,getHolidays(y));
return holidayCache.get(y).get(dateKey(y,date.getMonth()+1,date.getDate()))||null;
}
function isClosed(date){
const dow=date.getDay();
const isHoliday=holidayName(date)!==null;
if(dow===1)return!isHoliday;
if(dow===2){
const day=date.getDate();
if(day>=15&&day<=21)return true;
const monday=new Date(date.getFullYear(),date.getMonth(),day-1);
if(holidayName(monday)!==null)return true;
}
return false;
}
function renderCalendar(today=new Date()){
const body=document.getElementById('calendar-body');
const caption=document.getElementById('calendar-caption');
if(!body||!caption)return;
const year=today.getFullYear();
const month=today.getMonth();
const firstDow=new Date(year,month,1).getDay();
const daysInMonth=new Date(year,month+1,0).getDate();
const fragment=document.createDocumentFragment();
let row=document.createElement('tr');
for(let i=0;i<firstDow;i+=1){
const td=document.createElement('td');
td.className='empty';
row.appendChild(td);
}
for(let day=1;day<=daysInMonth;day+=1){
const date=new Date(year,month,day);
const closed=isClosed(date);
const holiday=holidayName(date);
const td=document.createElement('td');
if(closed)td.classList.add('closed');
if(holiday)td.classList.add('holiday');
if(day===today.getDate()){
td.classList.add('today');
td.setAttribute('aria-current','date');
}
const num=document.createElement('span');
num.className='day-num';
num.textContent=day;
td.appendChild(num);
if(holiday){
const label=document.createElement('span');
label.className='day-label holiday-label';
const full=document.createElement('span');
full.className='label-full';
full.textContent=holiday;
const short=document.createElement('span');
short.className='label-short';
short.setAttribute('aria-hidden','true');
short.textContent='祝日';
label.append(full,short);
td.appendChild(label);
}
if(closed){
const label=document.createElement('span');
label.className='day-label';
label.textContent='定休日';
td.appendChild(label);
}
row.appendChild(td);
if(date.getDay()===6||day===daysInMonth){
while(row.children.length<7){
const empty=document.createElement('td');
empty.className='empty';
row.appendChild(empty);
}
fragment.appendChild(row);
row=document.createElement('tr');
}
}
caption.textContent=`${year}年${month+1}月の営業日`;
body.replaceChildren(fragment);
}
const NOTES_MAX=1000;
const PEOPLE_MAX=5;
const SEND_ERROR='送信できませんでした。時間をおいて再度お試しいただくか、お電話（000-0000-0000）でご予約ください。';
const todayKey=(d=new Date())=>dateKey(d.getFullYear(),d.getMonth()+1,d.getDate());
const validators={
name(value){
if(!value.trim())return'お名前を入力してください。';
if(value.trim().length>100)return'お名前は100文字以内で入力してください。';
return'';
},
email(value){
const v=value.trim();
if(!v)return'メールアドレスを入力してください。';
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return'メールアドレスの形式が正しくありません（例：name@example.com）。';
return'';
},
phone(value){
const v=value.trim();
if(!v)return'';
if(!/^[0-9-]+$/.test(v))return'電話番号は半角数字とハイフンで入力してください。';
const digits=v.replace(/-/g,'');
if(digits.length<10||digits.length>11)return'電話番号は10〜11桁で入力してください。';
return'';
},
date(value){
if(!value)return'希望日を選んでください。';
if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return'希望日の形式が正しくありません。';
if(value<todayKey())return'希望日には今日以降の日付を選んでください。';
return'';
},
time(value){
if(!value)return'希望時間を選んでください。';
if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(value))return'希望時間の形式が正しくありません。';
return'';
},
people(value){
const v=value.trim();
const n=Number(v);
if(!v)return'人数を入力してください。';
if(!Number.isInteger(n)||n<1||n>PEOPLE_MAX)return`人数は1〜${PEOPLE_MAX}の数字で入力してください。`;
return'';
},
notes(value){
if(value.trim().length>NOTES_MAX)return`備考は${NOTES_MAX}文字以内で入力してください。`;
return'';
},
agree(_value,input){
return input.checked?'':'個人情報の取り扱いへの同意にチェックを入れてください。';
},
};
function validateField(input){
const check=validators[input.name];
if(!check)return true;
const message=check(input.value,input);
const error=document.getElementById(`${input.id}-error`);
if(error)error.textContent=message;
input.setAttribute('aria-invalid',message?'true':'false');
return message==='';
}
function updateCharCount(textarea){
const counter=document.getElementById(`${textarea.id}-count`);
if(!counter)return;
const length=textarea.value.trim().length;
counter.textContent=`${length} / ${NOTES_MAX}文字`;
counter.classList.toggle('over',length>NOTES_MAX);
}
function collectReservation(form){
const data={};
for(const el of form.elements){
if(!el.name)continue;
data[el.name]=el.type==='checkbox'?(el.checked?el.value:''):el.value;
}
return data;
}
async function sendReservation(endpoint,data){
const response=await fetch(endpoint,{
method:'POST',
headers:{'Content-Type':'text/plain;charset=utf-8'},
body:JSON.stringify(data),
});
if(!response.ok)throw new Error(`HTTP ${response.status}`);
return response.json();
}
function setupReservationForm(){
const form=document.getElementById('reservation-form');
if(!form)return;
const result=document.getElementById('form-result');
const submit=document.getElementById('reservation-submit');
const fields=[...form.querySelectorAll('input, textarea')].filter((el)=>validators[el.name]);
const notes=form.elements.notes;
let sending=false;
if(form.elements.date)form.elements.date.min=todayKey();
const showResult=(text,isError)=>{
result.textContent=text;
result.classList.toggle('is-error',isError);
};
for(const input of fields){
input.addEventListener('blur',()=>validateField(input));
const onChange=()=>{
if(input.getAttribute('aria-invalid')==='true')validateField(input);
if(input===notes)updateCharCount(input);
if(!sending)showResult('',false);
};
input.addEventListener('input',onChange);
input.addEventListener('change',onChange);
}
form.addEventListener('submit',async(event)=>{
event.preventDefault();
if(sending)return;
const invalid=fields.filter((input)=>!validateField(input));
if(invalid.length>0){
showResult('入力内容に誤りがあります。赤字の項目をご確認ください。',true);
invalid[0].focus();
return;
}
sending=true;
submit.disabled=true;
submit.textContent='送信中…';
showResult('送信しています…',false);
try{
const reply=await sendReservation(form.dataset.endpoint,collectReservation(form));
if(reply&&reply.ok){
form.reset();
for(const input of fields){
input.removeAttribute('aria-invalid');
const error=document.getElementById(`${input.id}-error`);
if(error)error.textContent='';
}
if(notes)updateCharCount(notes);
showResult('ご予約を受け付けました。ありがとうございました。',false);
}else{
showResult((reply&&reply.message)||SEND_ERROR,true);
}
}catch(err){
showResult(SEND_ERROR,true);
}finally{
sending=false;
submit.disabled=false;
submit.textContent='予約する';
}
});
}
function trackHeaderHeight(){
const header=document.querySelector('.site-header');
if(!header)return;
let last=-1;
const apply=(height)=>{
const h=Math.round(height);
if(h===last)return;
last=h;
document.documentElement.style.scrollPaddingTop=`${h+8}px`;
};
if('ResizeObserver'in window){
new ResizeObserver(([entry])=>{
const box=entry.borderBoxSize&&entry.borderBoxSize[0];
apply(box?box.blockSize:entry.target.offsetHeight);
}).observe(header);
}else{
const measure=()=>requestAnimationFrame(()=>apply(header.offsetHeight));
measure();
window.addEventListener('resize',measure);
}
}
if(typeof document!=='undefined'){
document.addEventListener('DOMContentLoaded',()=>{
renderCalendar();
setupReservationForm();
trackHeaderHeight();
});
}
